sys_script_client.script:
// MSSCUSTODY-5334 - Script to dynamically manage fields based on Bulk Field Group selection
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        var outcomeVal = g_form.getValue('outcome').toLowerCase();
        if (outcomeVal.indexOf('amend') > -1) {
            g_form.setMandatory('bulk_field_group', true);
            g_form.setDisplay('bulk_field_group', true);
        } else {
            g_form.setMandatory('bulk_field_group', false);
            g_form.setDisplay('bulk_field_group', false);
        }
        handleInitialLoad(newValue);
        return;
    }
    //MSSCUSTODY-7042
    if (newValue == "Settle Trade") {
        g_form.setValue('settlement_type', 'B');
    }
    if (newValue == "Process Trade Cancellation") {
        g_form.setValue('cancel_by', 'C');
    }

    //  Save current value (MSSCUSTODY-5860)
    var currentBulkValue = g_form.getValue('bulk_field_group');

    // Perform eligibility check
    var eligbleCheck = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
    eligbleCheck.addParam('sysparm_name', 'evalAmendEligibility');
    eligbleCheck.addParam('sysparm_recOutcome', g_form.getValue('outcome'));
    eligbleCheck.addParam('sysparm_recSysID', g_form.getUniqueValue());
    eligbleCheck.addParam('sysparm_tableName', 'x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
    eligbleCheck.getXMLAnswer(function(response) {
        handleEligibility(response, currentBulkValue); // Pass preserved value
    });

    function handleInitialLoad(newValue) {
        var fieldsToHideOnLoad = getFieldsToHide();
        fieldsToHideOnLoad.forEach(function(field) {
            g_form.setDisplay(field, false);
        });

        if (newValue === '') {
            return;
        }
    }

    // Handle eligibility response
    function handleEligibility(check, previousValue) {
        if (check.toString() === 'true') {
            // Restore previous selection
            if (previousValue) {
                g_form.setValue('bulk_field_group', previousValue);
            }
            manageFieldsBasedOnEligibility();
        } else {
            g_form.setMandatory('bulk_field_group', false);
            g_form.setDisplay('bulk_field_group', false);
            g_form.clearValue('bulk_field_group');
        }
    }

    function manageFieldsBasedOnEligibility() {
        var fieldsToHide = getFieldsToHide();
        var bulkFieldGroup = g_form.getValue('bulk_field_group');
        var fieldGroupToShow = getFieldGroupToShow(bulkFieldGroup);

        fieldsToHide.forEach(function(field) {
            g_form.setDisplay(field, false);
            //g_form.clearValue(field);
        });

        fieldGroupToShow.forEach(function(field) {
            g_form.setDisplay(field, true);
        });

        if (parseInt(g_form.getValue('active_trade_count')) > 1) {
            g_form.setMandatory('bulk_field_group', true);
            g_form.setDisplay('bulk_field_group', true);
        } else {
            fieldsToHide.forEach(function(field) {
                g_form.setDisplay(field, true);
            });

            // MSSCUSTODY 6915 - Added logic to remove extra fields from bulk form like deal price, settlement currency, etc
            g_form.setDisplay('amend_deal_price', false);
            g_form.setDisplay('amend_settlement_amount', false);
            g_form.setDisplay('amend_settlement_currency', false);
            g_form.setDisplay('amend_deal_currency', false);

        }

    }
    //getFieldsToHideFromBulk.forEach(function(field) { //hiding fields not needed on Bulk
    // g_form.setDisplay(field, false);
    //});

    function getFieldsToHide() {
        return [
            'amend_settlement_currency',
            'amend_deal_price',
            'amend_settlement_amount',
            'settlement_date',
            'amend_trade_date',
            'amend_location_code',
            'security_id_sec_id',
            'counterparty_reference',
            'customer_reference',
            'amend_payment_method',
            'amend_switch_indicator',
            'amend_switch_account',
            'amend_suspense_account_number',
            'amend_counterparty_settlement_account_number',
            'amend_convert_to_account_switching',
            'amend_a_c_of_client',
            'amend_deliverer_custodian_bic_receiver_custodian_bic',
            'amend_seller_bic_buyer_bic',
            'amend_receiver_custodian_bic', // MSSCUSTODY-7159 - Added Receiver Custodian (BIC)
            'amend_buyer_bic', // MSSCUSTODY-7159 - Added Buyer (BIC)
            'amend_place_of_settlement_bic',
            'amend_gdi_indicator',
            'amend_counterparty_code',
            'amend_hmi_indicator',
            'amend_cash_hold_indicator',
            'amend_script_hold_indicator',
            'amend_deal_currency',
            'amend_charges_ccy',
            'amend_charges_amt',
            'amend_charges_type',
            // MSSCUSTODY 5862 - Added remote table fields 
            'amend_security_id_sec_id_ref',
            'amend_switch_account_ref',
            'amend_counterparty_code_ref',
            'amend_nssc',
			'amend_swh', // MSSCuSTODY-7898 - Added SWH
			'amend_fa', //MSSCUSTODY-8183- Added Fa
			'amend_iss',
			'amend_switch_reference'
        ];
    }

    function getFieldGroupToShow(bulkFieldGroup) {
        var fieldGroups = {
            'customer_reference': ['customer_reference'],
            'trade_settl_date': ['amend_trade_date', 'settlement_date','amend_swh'],
            'cash_hold_indicator': ['amend_cash_hold_indicator'],
            'beneficiary_details': [
                'amend_a_c_of_client',
                'amend_deliverer_custodian_bic_receiver_custodian_bic',
                'amend_seller_bic_buyer_bic',
                'amend_place_of_settlement_bic',
				'amend_receiver_custodian_bic', // MSSCUSTODY-7159 - Added Receiver Custodian (BIC)
				'amend_buyer_bic', // MSSCUSTODY-7159 - Added Buyer (BIC)
            ],
            'counterparty_details': [
                'counterparty_reference',
                'amend_payment_method',
                'amend_counterparty_code',
                'amend_counterparty_settlement_account_number',
                'amend_counterparty_code_ref'
            ],
            'location_gdi': ['amend_location_code', 'amend_gdi_indicator'],
            'hmi_indicator​': ['amend_hmi_indicator'],
            'script_hold_indicator': ['amend_script_hold_indicator'],
            'amendment_charges': ['amend_charges_ccy', 'amend_charges_amt', 'amend_charges_type'],
            'security_id': ['amend_security_id_sec_id_ref', 'security_id_sec_id'],
            'blank_trade_date': [],
			'fa': ['amend_fa'],
			'iss': ['amend_iss']
        };

        return fieldGroups[bulkFieldGroup] || [];
    }

}
